using System.Collections.Generic;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "ChantingAction", menuName = "Data/Battle/Battle Actions/Sothis/Chanting Action")]
public class ChantingAction : BattleAction
{
	[Header("Chanting Action")]
	[SerializeField]
	private PurifyAction purifyAction;

	[SerializeField]
	private ChantingEffect chantingEffect;

	[SerializeField]
	protected DefaultEffectAction gainChantingEffectAction;

	[SerializeField]
	private int gainChantingEffectAmount;

	public ChantingEffect ChantingEffect => chantingEffect;

	public DefaultEffectAction GainChantingEffectAction => gainChantingEffectAction;

	public int GainChantingEffectAmount => gainChantingEffectAmount;

	public int PurifyAmount()
	{
		int num = 0;
		num = ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.GetComponent<UnitEffects>().IsEffectActiveGetAmount(chantingEffect, activateFeedback: false);
		return 1 + num;
	}

	public override void CastTarget(GameObject target, GameObject source)
	{
		purifyAction.CastTargetAmountChanting(target, PurifyAmount(), source);
		AddChantingToPlayer(source, gainChantingEffectAmount);
		SpawnVFX(GetVFXOwnerPosition(target), 3f);
	}

	public override void AreaCastTarget(List<GameObject> targets, GameObject source)
	{
		purifyAction.AreaCastTargetAmountChanting(targets, PurifyAmount(), source);
		for (int i = 0; i < targets.Count; i++)
		{
			SpawnVFX(GetVFXOwnerPosition(targets[i]), 3f);
		}
		AddChantingToPlayer(source, gainChantingEffectAmount);
	}

	protected void AddChantingToPlayer(GameObject source, int amount)
	{
		gainChantingEffectAction.CastTargetAmount(ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject, amount, source);
	}
}
